def transform(grid):
    h, w = len(grid), len(grid[0])
    output = [[0 for _ in range(5)] for _ in range(5)]

    # Process each input cell
    # Corner cells (r=0/2, c=0/2): 2x2 block at (2*r, 2*c)
    if (h >= 2 and w >= 2):
        for rr in [0, 2]:
            for cc in [0, 2]:
                if 0 <= rr < h and 0 <= cc < w:
                    val = grid[rr][cc]
                    for di in range(2):
                        for dj in range(2):
                            oi = 2 * rr + di
                            oj = 2 * cc + dj
                            if 0 <= oi < 5 and 0 <= oj < 5:
                                output[oi][oj] = val

    # Edge cells (r=0/2, c=1): 2x1 block at (2*r, 2*c) 
    for rr in [0, 2]:
        if 0 <= rr < h and 0 <= 1 < w:
            val = grid[rr][1]
            for di in range(2):
                for dj in range(1):
                    oi = 2 * rr + di
                    oj = 2 * 1 + dj
                    if 0 <= oi < 5 and 0 <= oj < 5:
                        # Check if not already filled by corner
                        if output[oi][oj] == 0:
                            output[oi][oj] = val

    # Middle row cells (r=1): 
    # Left edge (r=1, c=0): 1x2 block at (2*r, 2*c)
    if 0 <= 1 < h and 0 <= 0 < w:
        val = grid[1][0]
        for di in range(1):
            for dj in range(2):
                oi = 2 * 1 + di
                oj = 2 * 0 + dj
                if 0 <= oi < 5 and 0 <= oj < 5:
                    if output[oi][oj] == 0:
                        output[oi][oj] = val

    # Right edge (r=1, c=2): 1x2 block at (2*r, 2*c)
    if 0 <= 1 < h and 0 <= 2 < w:
        val = grid[1][2]
        for di in range(1):
            for dj in range(2):
                oi = 2 * 1 + di
                oj = 2 * 2 + dj
                if 0 <= oi < 5 and 0 <= oj < 5:
                    if output[oi][oj] == 0:
                        output[oi][oj] = val

    # Center (r=1, c=1): 1x1 block at (2*r+1, 2*c+1) = (3,3)
    if 0 <= 1 < h and 0 <= 1 < w:
        val = grid[1][1]
        oi = 2 * 1 + 1
        oj = 2 * 1 + 1
        if 0 <= oi < 5 and 0 <= oj < 5:
            if output[oi][oj] == 0:
                output[oi][oj] = val

    return output

